-- Comparación con documentos de otra empresa (InstalCorp) detectó dos
-- procedimientos a los que les faltaban subtemas exigidos por la ley:
-- Extintores (clase de fuego K/F, tipos de extintor e inspección/mantención)
-- y TMERT-EESS (identificación/evaluación ergonómica y controles administrativos).

UPDATE erp.procedimientos_capacitacion SET objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco legal: Ley N°16.744 (Art. 68) y D.S. N°594 del Ministerio de Salud (Art. 45-46, extintores portátiles).\n• Qué es el fuego y cómo se produce (triángulo/tetraedro del fuego: combustible, oxígeno, calor y reacción en cadena).\n• Tipos de fuego: Clase A (sólidos combustibles), B (líquidos y gases inflamables), C (equipos energizados), D (metales combustibles) y K/F (aceites y grasas de cocina).\n• Tipos de extintores y su aplicación según tipo de fuego (agua, PQS, CO2, espuma, extintores especiales).\n• Cantidad y ubicación de extintores según superficie protegida (D.S. N°594 Art. 46), altura de instalación y señalización.\n• Inspección y mantención periódica de los extintores.\n• Forma correcta de combatir el fuego y cuándo NO intentar hacerlo (no dar la espalda al fuego, retirarse si no se controla en pocos segundos).\n• Responsabilidades del trabajador y del empleador.'
WHERE codigo = '01';

UPDATE erp.procedimientos_capacitacion SET objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco legal: Ley N°16.744 sobre accidentes y enfermedades profesionales, D.S. N°594, Protocolo de Vigilancia TMERT-EESS (Res. Ex. MINSAL vigente) y Guía Técnica TMERT Extremidad Superior.\n• Qué son los TMERT de Extremidad Superior (EESS) y su importancia en la prevención.\n• Principales lesiones: tendinitis, síndrome del túnel carpiano, epicondilitis, lesiones de hombro, y sus síntomas de alerta.\n• Identificación y evaluación de riesgos: identificación de tareas críticas, evaluación de puestos de trabajo, métodos de observación ergonómica y listas de chequeo.\n• Controles administrativos y medidas personales: rotación de tareas, pausas activas, organización del trabajo, higiene postural y ejercicios preventivos.\n• Responsabilidades del trabajador y del empleador.'
WHERE codigo = '21';
